<template>
    <div class="modal fade" id="preview" tabindex="-1" role="dialog" aria-labelledby="editModalLabel" aria-hidden="true">
    <div class="modal-dialog modal-fullscreen modal-dialog-scrollable" role="document"> <!-- Changed to modal-xl and added scrollable -->
        <div class="modal-content"> <!-- Added min-height -->
            <div class="modal-header">
                <h5 class="modal-title" id="editModalLabel">WORK ORDER NO#{{ workOrder.order_no }}</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
            </div>
            <div class="modal-body">
                <span v-if="loading" v-html="tableShimmer()"></span>

               <table v-else class="table table-bordered" >
    <tbody>
        <tr>
            <th>Work Order for</th>
            <td>{{ workOrder.order_group }}</td>
            <th>Requester</th>
            <td>{{ workOrder.issuer }}</td>
        </tr>
        <tr>
            <th>Project</th>
            <td>{{workOrder.project }}</td>
            <th>Date Requested</th>
            <td>{{ formatDate(workOrder.date) }}</td>

        </tr>


        <tr>
            <th>Description</th>
            <td colspan="3">{{ workOrder.description }}</td>
        </tr>
    </tbody>
</table>

<h6> {{ workOrder?.order_group?.toUpperCase() }} REQUIRED</h6>
<span v-if="loading" v-html="tableShimmer()"></span>

               <table v-else class="table table-bordered" >
    <tbody>
          <tr>
            <th>Sno</th>
            <th>Item</th>
            <th>Quantity</th>
            <th>Unit</th>
        </tr>

        <tr v-for="(item ,index) in workOrder.work_order_items">
            <td>{{ index + 1 }}</td>
            <td>{{ item.item }}</td>
            <td>{{ item.quantity }}</td>
            <td>{{ item.unit }}</td>
        </tr>

    </tbody>
</table>
<h5 class="fw-bold mt-5 mb-2">FABRICATION WORK</h5>
<h6 class="fw-bold fst-italic">Items Used </h6>
<span v-if="loading" v-html="tableShimmer()"></span>

               <table v-else class="table table-bordered" >
    <tbody>
          <tr>
            <th>Sno</th>
            <th>Item</th>
            <th>Quantity</th>
            <th>Unit</th>
        </tr>

        <tr v-for="(item ,index) in workOrder.items_used">
            <td>{{ index + 1 }}</td>
            <td>{{ item.item }}</td>
            <td>{{ item.quantity }}</td>
            <td>{{ item.unit }}</td>
        </tr>
    </tbody>
</table>
<p class="text-center" v-if="workOrder.items_used == 0">No Item Used</p>


<h6 class="fw-bold fst-italic">Items Produced </h6>
<span v-if="loading" v-html="tableShimmer()"></span>

               <table v-else class="table table-bordered" >
    <tbody>
          <tr>
            <th>Sno</th>
            <th>Item</th>
            <th>Quantity</th>
            <th>Unit</th>
        </tr>

        <tr v-for="(item ,index) in workOrder.items_produced">
            <td>{{ index + 1 }}</td>
            <td>{{ item.item }}</td>
            <td>{{ item.quantity }}</td>
            <td>{{ item.unit }}</td>
        </tr>

    </tbody>
</table>
<p class="text-center" v-if="workOrder.items_produced == 0">No Item Produced</p>


<h6 class="fw-bold fst-italic">Wastes Produced </h6>
<span v-if="loading" v-html="tableShimmer()"></span>
               <table v-else class="table table-bordered" >
    <tbody>
          <tr>
            <th>Sno</th>
            <th>Item</th>
            <th>Quantity</th>
            <th>Unit</th>
        </tr>

        <tr v-for="(item ,index) in workOrder.waste_produced">
            <td>{{ index + 1 }}</td>
            <td>{{ item.item }}</td>
            <td>{{ item.quantity }}</td>
            <td>{{ item.unit }}</td>
        </tr>

    </tbody>
</table>
<p class="text-center" v-if="workOrder.waste_produced == 0">No Waste Produced</p>


            </div>
            <div class="modal-footer">
                <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>
            </div>
        </div>
    </div>
</div>

</template>

<script setup>
    import { onMounted, ref,inject,watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Work Order' });
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const tableShimmer = inject('tableShimmer')
    
    const formatDate = inject('formatDate');

    const name = ref('');
    const short_name = ref('');
    const status = ref('');
    const showMessage = inject('showMessage');
    const showError = inject('showError');

const props = defineProps({
    workOrderId: String
});



const workOrder = ref('')
const loading = ref(false)
const getWorkOrder = async (id)=>{
    loading.value = true
  try{
    const response = await axiosInstance.get(`work-orders/${id}`)
    workOrder.value = response.data
  }catch(error){
   showError(error.message)
   console.log(error)
  }finally{
loading.value = false  
}

}

watch(
    () => props.workOrderId,
    (newId) => {
        if (newId) {
            getWorkOrder(newId);
        }
    },
    { immediate: true }
);


    const resetForm = () => {
    name.value = '';
    short_name.value = '';
    status.value = '';
};






    onMounted(() => {

    });
</script>